18	CREATE TABLE IF NOT EXISTS seat (
19	    experiment_id VARCHAR(64) NOT NULL,
20	    block_no      INT         NOT NULL,
21	    seat_no       INT         NOT NULL,
22	    treatment     VARCHAR(1)  NOT NULL,
23	    CONSTRAINT pk_seat PRIMARY KEY (experiment_id, block_no, seat_no),
24	    CONSTRAINT ck_seat_block_no CHECK (block_no >= 1),
25	    CONSTRAINT ck_seat_seat_no CHECK (seat_no BETWEEN 1 AND 4),
26	    CONSTRAINT ck_seat_treatment CHECK (treatment IN ('A', 'B'))
27	);
28	COMMENT ON TABLE  seat IS '席位表（处理映射）：每区组4席，按提交顺序固定两个A两个B，之后不可改；仅保存于数据库';
29	COMMENT ON COLUMN seat.experiment_id IS '所属实验编号';
30	COMMENT ON COLUMN seat.block_no IS '区组号，从1开始，按区组顺序分配';
31	COMMENT ON COLUMN seat.seat_no IS '区组内席位号1~4，属于可直接解码信息，禁止通过普通接口暴露';
32	COMMENT ON COLUMN seat.treatment IS '处理代码 A 或 B，盲底，仅揭盲批准后可返回给申请人';
33	
34	CREATE TABLE IF NOT EXISTS allocation (
35	    id             BIGINT       NOT NULL AUTO_INCREMENT,
36	    experiment_id  VARCHAR(64)  NOT NULL,
37	    participant_id VARCHAR(64)  NOT NULL,
38	    block_no       INT          NOT NULL,
39	    seat_no        INT          NOT NULL,
40	    blind_code     VARCHAR(32)  NOT NULL,
41	    status         VARCHAR(16)  NOT NULL,
42	    assigned_actor VARCHAR(64)  NOT NULL,
43	    assigned_at    BIGINT       NOT NULL,
44	    withdrawn_at   BIGINT,
45	    CONSTRAINT pk_allocation PRIMARY KEY (id),
46	    CONSTRAINT uq_allocation_participant UNIQUE (experiment_id, participant_id),
47	    CONSTRAINT uq_allocation_seat UNIQUE (experiment_id, block_no, seat_no),
48	    CONSTRAINT uq_allocation_blind_code UNIQUE (blind_code),
49	    CONSTRAINT ck_allocation_status CHECK (status IN ('ASSIGNED', 'WITHDRAWN'))
50	);
