                        + "FROM blind_sample s JOIN allocation a ON a.id = s.allocation_id "
                        + "WHERE s.experiment_id = ? AND s.result_value IS NOT NULL "
                        + "AND a.status = 'ASSIGNED'",
                (rs, n) -> new SummaryRow(rs.getLong("c"), rs.getLong("total")),
